import {animals} from './data.js';
const names=['개혁가','조력가','성취가','개성가','탐구가','충실가','열정가','도전가','평화주의자'];
export function typeCarousel(){return `<section id="types" class="section type-section" aria-label="아홉 가지 유형 소개"><div class="section-heading reveal"><span class="eyebrow">NINE TYPES / 아홉 가지 시선</span><div><h2>다른 마음, 다른 강점.<br>아홉 유형을 만나보세요.</h2><p>각 유형의 특징을 동물 친구와 함께 살펴보세요.<br>동물은 이해를 돕기 위해 인사이트가 선택한 상징입니다.</p></div></div><div class="type-controls"><span class="type-position" aria-live="polite">01 / 09</span><div><button class="icon-button" type="button" data-type-prev aria-label="이전 유형" disabled>←</button><button class="icon-button" type="button" data-type-next aria-label="다음 유형">→</button></div></div><div class="type-track" tabindex="0" role="region" aria-label="좌우로 넘기는 유형 카드">${animals.map((a,i)=>`<article class="type-card" aria-label="${a.id}번 유형 ${names[i]}"><div class="type-art" style="background:${a.color}"><span class="type-badge">TYPE ${String(a.id).padStart(2,'0')}</span><img src="/assets/animal-${a.id}.png" alt="${a.name} 전신 3D 클레이 이미지" width="600" height="600" loading="lazy"></div><div class="type-copy"><span class="eyebrow">${a.id}번 유형 / ${names[i]}</span><h3>${a.title}</h3><p class="type-tag">${a.tag}</p><p>${a.description}</p><div class="type-growth"><span>나를 위한 작은 연습</span><p>${a.growth}</p></div></div></article>`).join('')}</div><div class="type-pagination" aria-label="유형으로 바로 이동">${animals.map(a=>`<button type="button" data-type-index="${a.id-1}" aria-label="${a.id}번 유형 보기" ${a.id===1?'aria-current="true"':''}>${a.id}</button>`).join('')}</div></section>`;}
export function bindTypeCarousel(){const track=document.querySelector('.type-track');if(!track)return;const cards=[...track.children],prev=document.querySelector('[data-type-prev]'),next=document.querySelector('[data-type-next]'),dots=[...document.querySelectorAll('[data-type-index]')];let index=0,frame=0;const go=i=>{const target=Math.max(0,Math.min(8,i));track.scrollTo({left:cards[target].offsetLeft-cards[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};const update=()=>{frame=0;if(!track.isConnected)return;index=cards.reduce((best,card,i)=>Math.abs(card.offsetLeft-cards[0].offsetLeft-track.scrollLeft)<Math.abs(cards[best].offsetLeft-cards[0].offsetLeft-track.scrollLeft)?i:best,0);prev.disabled=index===0;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-2;dots.forEach((b,i)=>i===index?b.setAttribute('aria-current','true'):b.removeAttribute('aria-current'));document.querySelector('.type-position').textContent=`${String(index+1).padStart(2,'0')} / 09`;};prev.addEventListener('click',()=>go(index-1));next.addEventListener('click',()=>go(index+1));dots.forEach((b,i)=>b.addEventListener('click',()=>go(i)));track.addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(update);},{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();go(index+(e.key==='ArrowRight'?1:-1));}});update();}
